 "content": "import os

from .provider import send
from .render import render


def _new_receipt_enabled():
    # The notifier is deployed separately and can't read the root flags.toml.
    return os.environ.get("NOTIFIER_FF_NEW_RECEIPT_EMAIL") == "1"


def send_receipt(invoice_id, to_addr, total_minor):
    template = "receipt_v2" if _new_receipt_enabled() else "receipt"
    body = render(template, invoice_id=invoice_id, total_minor=total_minor)
    return send(to_addr, "Your receipt", body)


def send_payment_reminder(invoice_id, to_addr):
    body = render("payment_reminder", invoice_id=invoice_id)
    return send(to_addr, "Payment reminder", body)
